package com.englishcoach.hangman;

import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import java.security.SecureRandom;
import java.util.*;
import java.util.function.Function;
import static com.englishcoach.hangman.HangmanRules.*;
import static com.englishcoach.hangman.HangmanRepository.*;

@Service
public final class HangmanService {
    private final HangmanRepository repository; private final HangmanCatalog catalog; private final TransactionTemplate tx; private final SecureRandom random=new SecureRandom();
    public HangmanService(HangmanRepository repository,HangmanCatalog catalog,PlatformTransactionManager manager){this.repository=repository;this.catalog=catalog;this.tx=new TransactionTemplate(manager);}
    public HangmanDtos.Bootstrap bootstrap(long user){return tx.execute(t->{var tracks=new ArrayList<HangmanDtos.Track>();for(Difficulty d:Difficulty.values()){var p=repository.progress(user,d);tracks.add(new HangmanDtos.Track(d,d.balloons,d.prefill,p.highest(),p.last(),catalog.count(d),p.current(),p.completed(),catalog.eligibleCount(d)));}return new HangmanDtos.Bootstrap(catalog.version(),tracks,"English words: existing SCOWL US/GB, OEWN and CEFR-J qualified lexicon. Copyright 2000–2026 Kevin Atkinson; Alan Beale. Original English Coach seed categories; learner eligibility from exact CEFR-J source references.","king-approved-core.cefrj",catalog.sourceEligibleCount());});}
    public HangmanDtos.Round get(long user,UUID id){return tx.execute(t->view(repository.owned(user,id)));}
    public HangmanDtos.Round start(long user,HangmanDtos.StartRequest request){return tx.execute(t->{Progress p=repository.lockTrack(user,request.difficulty());String key="START:"+request.difficulty()+":"+request.levelNumber();UUID replay=repository.replay(user,request.requestId(),key);if(replay!=null)return view(repository.owned(user,replay));int level=request.levelNumber()==null?p.last():request.levelNumber();if(level>p.highest())throw new HangmanException(409,"LEVEL_LOCKED");catalog.level(request.difficulty(),level);StoredRound current=p.current()==null?null:repository.owned(user,p.current());if(current!=null&&current.state().status()==Status.ACTIVE){repository.receipt(user,request.requestId(),key,current.id());return view(current);}StoredRound created=create(user,request.difficulty(),level,current==null?null:current.state().answer());repository.receipt(user,request.requestId(),key,created.id());return view(created);});}
    public HangmanDtos.Round guess(long user,UUID id,HangmanDtos.GuessRequest request){String letter=request.letter().toUpperCase(Locale.ROOT);return command(user,id,request.requestId(),"GUESS:"+id+":"+letter+":"+request.expectedVersion(),round->{if(round.state().used(letter.charAt(0))||round.state().status()!=Status.ACTIVE)return round;checkVersion(round,request.expectedVersion());return apply(round,HangmanRules.guess(round.state(),letter));});}
    public HangmanDtos.Round hint(long user,UUID id,HangmanDtos.HintRequest request){return command(user,id,request.requestId(),"HINT:"+id+":"+request.expectedVersion(),round->{if(round.state().status()!=Status.ACTIVE||round.state().hinted().length()>=2)return round;checkVersion(round,request.expectedVersion());return apply(round,HangmanRules.hint(round.state(),random));});}
    public HangmanDtos.Round retry(long user,UUID id,HangmanDtos.RetryRequest request){return command(user,id,request.requestId(),"RETRY:"+id,round->{if(round.state().status()==Status.ACTIVE)throw new HangmanException(409,"ROUND_NOT_FINISHED");var p=repository.progress(user,round.state().difficulty());if(!id.equals(p.current())){var current=repository.owned(user,p.current());if(current.state().status()!=Status.ACTIVE)throw new HangmanException(409,"ROUND_CHANGED");return current;}return create(user,round.state().difficulty(),round.level(),round.state().answer());});}
    private HangmanDtos.Round view(StoredRound round){var s=round.state();var progress=repository.progress(round.userId(),s.difficulty());List<String> correct=new ArrayList<>(),wrong=new ArrayList<>();for(char c:s.guessed().toCharArray())(s.answer().indexOf(c)>=0?correct:wrong).add(String.valueOf(c));return new HangmanDtos.Round(round.id(),s.difficulty(),round.level(),round.category(),s.pattern(),letters(s.prefilled()),correct,wrong,letters(s.hinted()),s.initialBalloons(),s.remaining(),2-s.hinted().length(),s.status(),s.version(),s.status()==Status.ACTIVE?null:s.score(),s.status()==Status.ACTIVE?null:s.answer(),s.status()==Status.WON&&round.level()<catalog.count(s.difficulty()),progress.completed());}
    private HangmanDtos.Round command(long user,UUID id,UUID request,String key,Function<StoredRound,StoredRound> action){return tx.execute(t->{var observed=repository.owned(user,id);repository.lockTrack(user,observed.state().difficulty());UUID replay=repository.replay(user,request,key);if(replay!=null)return view(repository.owned(user,replay));StoredRound result=action.apply(repository.owned(user,id));repository.receipt(user,request,key,result.id());return view(result);});}
    private void checkVersion(StoredRound round,Integer version){if(version==null||round.state().version()!=version)throw new HangmanException(409,"ROUND_CHANGED");}
    private StoredRound create(long user,Difficulty d,int n,String replacedAnswer){var level=HangmanWordSelection.select(catalog.pool(d),catalog.level(d,n),repository.encounters(user),random,replacedAnswer);return repository.insert(user,level,HangmanRules.start(level.answer(),d,random));}
    private StoredRound apply(StoredRound round,Transition transition){if(!transition.changed())return round;var result=repository.save(round,transition.state());if(result.state().status()==Status.WON)repository.unlock(result,catalog.count(result.state().difficulty()));return result;}
    private List<String> letters(String values){return values.chars().mapToObj(c->String.valueOf((char)c)).toList();}
}
